export {clock,placeName,homes} from './sim.mjs';
import {placeName} from './sim.mjs';
export const END=480;
export const catalog={S:{name:'Neurosurgeon',kind:'staff',home:'OFFICE',rate:180},N:{name:'Circulating nurse',kind:'staff',home:'WORK',rate:55},A:{name:'Anesthesia professional',kind:'staff',home:'LOUNGE',rate:130},T:{name:'Scrub technologist',kind:'staff',home:'WORK',rate:45},US:{name:'Ultrasound',kind:'equipment',home:'HUB',purchase:60000,maintenance:20},MC:{name:'Surgical microscope',kind:'equipment',home:'HUB',purchase:450000,maintenance:80},NV:{name:'Navigation cart',kind:'equipment',home:'HUB',purchase:250000,maintenance:50}};
export const defaultConfig=()=>({counts:{S:2,N:2,A:2,T:2,US:1,MC:1,NV:1},types:{cranial:{name:'Cranial tumor case',duration:90,requires:{S:1,N:1,A:1,T:1,US:1,MC:1,NV:1}},spine:{name:'Spinal decompression',duration:75,requires:{S:1,N:1,A:1,T:1,US:0,MC:1,NV:0}}},assignments:['cranial','spine','cranial','spine','cranial','spine'],conflict:0,delayRate:25,missPenalty:10000,capitalMode:'daily',usefulDays:1250});
const schedule=[['A',1,10],['B',2,30],['C',3,50],['D',1,130],['E',2,150],['F',3,170]];
export function simulateGame(config,until=END){
 const cases=schedule.map(([id,room,plan],i)=>({id,room,plan,type:config.assignments[i],...structuredClone(config.types[config.assignments[i]]),start:null,end:null,ready:null,discharge:null,arrived:false,dispatch:null,assigned:[],blockers:[],everBlocked:false}));
 const resources=Object.entries(catalog).flatMap(([type,item])=>Array.from({length:config.counts[type]},(_,i)=>({id:`${type}${i+1}`,type,role:type,kind:item.kind,location:item.home,status:'Available',motion:null,owner:null})));const state={cases,resources,staff:resources.filter(r=>r.kind==='staff'),equipment:resources.filter(r=>r.kind==='equipment'),events:[],time:until};
 let queue=[],seq=0,now=0;const push=(time,type,data={})=>queue.push({time,type,data,seq:seq++});const log=(text,entity,kind='flow')=>state.events.push({time:now,text,entity,kind});
 const trip=(r,to,at)=>{push(at,'depart',{id:r.id,to});push(at+2,'arrive',{id:r.id,to})};
 cases.forEach(c=>{push(Math.max(0,c.plan-15),'patient',{id:c.id});push(c.plan-2,'dispatch');push(c.plan,'due')});
 function readyRoom(c){return !cases.some(p=>p.room===c.room&&p.plan<c.plan&&(p.ready===null||p.ready>now))}
 function blockers(c){let result=[];if(!readyRoom(c))result.push(`OR ${c.room} / turnover`);for(const [type,n] of Object.entries(c.requires)){const available=resources.filter(r=>r.type===type&&r.status==='Available').length;if(n>available)result.push(`${catalog[type].name}: need ${n}, free ${available}`)}return result}
 function dispatch(){for(const c of cases){if(c.start!==null||c.dispatch!==null||now<c.plan-2||!c.arrived)continue;c.blockers=blockers(c);if(c.blockers.length)continue;c.dispatch=now;c.blockers=[];for(const [type,n]of Object.entries(c.requires)){for(const r of resources.filter(r=>r.type===type&&r.status==='Available').slice(0,n)){r.status='Reserved';r.owner=c.id;c.assigned.push(r.id);trip(r,`OR${c.room}`,now)}}push(Math.max(c.plan,now+2),'start',{id:c.id});log(`Case ${c.id}: resources reserved, moving to OR ${c.room}`,c.id,'movement')}}
 while(queue.length){queue.sort((a,b)=>a.time-b.time||a.seq-b.seq);const e=queue.shift();if(e.time>until)break;now=e.time;const c=cases.find(c=>c.id===e.data.id),r=resources.find(r=>r.id===e.data.id);
 if(e.type==='patient'){c.arrived=true;log(`P-${c.id} arrives in pre-op`,c.id)}
 if(e.type==='depart'){r.motion={from:r.location,to:e.data.to,depart:now,arrive:now+2};r.location='CORRIDOR';r.status='In transit';log(`${r.id}: ${placeName(r.motion.from)} → ${placeName(e.data.to)}`,r.id,'movement')}
 if(e.type==='arrive'){r.location=e.data.to;r.motion=null;r.status=r.location.startsWith('OR')?'Reserved':'Turnaround';log(`${r.id} arrives at ${placeName(r.location)}`,r.id,'movement')}
 if(e.type==='start'){const assigned=c.assigned.map(id=>resources.find(r=>r.id===id));if(!assigned.every(r=>r.location===`OR${c.room}`&&!r.motion)){push(now+.001,'start',e.data);continue}c.start=now;c.end=now+c.duration+(c.id==='A'?config.conflict:0);assigned.forEach(r=>r.status='In case');log(`Case ${c.id} starts · ${c.name}${now>c.plan?` · ${Math.round(now-c.plan)} min late`:''}`,c.id,now>c.plan?'delay':'flow');push(c.end,'finish',{id:c.id});push(c.end+15,'turnover',{id:c.id});push(c.end+30,'discharge',{id:c.id});for(const r of assigned.filter(r=>r.type==='US'))push(Math.min(c.end,c.start+15+(c.id==='A'?config.conflict:0)),'release',{id:r.id})}
 if(e.type==='release'){if(r.status==='Cleaning'||r.status==='Turnaround')continue;r.status='Cleaning';log(`${r.id} released · 3 min cleaning`,r.id);trip(r,'HUB',now+3);push(now+5,'free',{id:r.id})}
 if(e.type==='finish'){log(`Case ${c.id} ends · P-${c.id} to recovery`,c.id);for(const id of c.assigned){const r=resources.find(r=>r.id===id);if(r.type==='US')continue;if(r.kind==='equipment')push(now,'release',{id});else{r.status='Turnaround';if(r.type==='A'){trip(r,'REC',now);trip(r,'LOUNGE',now+5)}else trip(r,catalog[r.type].home,now+(r.type==='N'?8:0));push(now+10,'free',{id})}}}
 if(e.type==='free'){r.owner=null;r.status='Available';log(`${r.id} available`,r.id)}
 if(e.type==='turnover'){c.ready=now;log(`OR ${c.room} turnover complete`,c.id)}
 if(e.type==='discharge'){c.discharge=now;log(`P-${c.id} leaves recovery`,c.id)}
 dispatch();
 for(const pending of cases.filter(c=>c.start===null&&c.dispatch===null&&now>=c.plan)){const b=blockers(pending);pending.blockers=b;if(b.length&&!pending.everBlocked){pending.everBlocked=true;log(`Case ${pending.id} blocked: ${b.join('; ')}`,pending.id,'blocked')}}
 }
 for(const c of cases.filter(c=>c.start===null)){if(c.dispatch!==null)c.blockers=['Assigned resources traveling to room'];else c.blockers=blockers(c)}
 if(until>=END)for(const c of cases.filter(c=>c.end===null||c.end>END))state.events.push({time:END,entity:c.id,kind:'missed',text:`Case ${c.id} not completed by 16:00 · fictional missed-case penalty`});
 return state;
}
export function delay(c,t){return Math.max(0,(c.start??Math.max(c.plan,t))-c.plan)}
export function status(c,t){return !c.arrived?'Not arrived':c.start===null?(t<c.plan?'In pre-op':c.dispatch!==null?'Resources traveling':'Waiting'):t<c.end?'In case':c.discharge===null?'Recovery':'Complete'}
export function reason(c,s){return c.start!==null?'Start recorded':s.time<c.plan?'Scheduled start not reached':c.blockers.join(' · ')||'Resource dispatch pending'}
export function costs(config,state){const elapsed=Math.min(END,state.time),fraction=elapsed/END;const payroll=Object.entries(catalog).filter(([,r])=>r.kind==='staff').reduce((a,[k,r])=>a+config.counts[k]*r.rate*elapsed/60,0);const capital=Object.entries(catalog).filter(([,r])=>r.kind==='equipment').reduce((a,[k,r])=>a+config.counts[k]*r.purchase,0);const equipment=(config.capitalMode==='upfront'?capital:capital/config.usefulDays*fraction);const maintenance=Object.entries(catalog).filter(([,r])=>r.kind==='equipment').reduce((a,[k,r])=>a+config.counts[k]*r.maintenance*fraction,0);const delayMinutes=state.cases.reduce((a,c)=>a+delay(c,elapsed),0);const delayCost=delayMinutes*config.delayRate;const missed=elapsed>=END?state.cases.filter(c=>c.end===null||c.end>END).length:0;const penalty=missed*config.missPenalty;const complete=state.cases.filter(c=>c.end!==null&&c.end<=elapsed).length;const late=state.cases.filter(c=>delay(c,elapsed)>0).length;return {payroll,capital,equipment,maintenance,delayCost,delayMinutes,missed,penalty,complete,late,total:payroll+equipment+maintenance+delayCost+penalty,win:elapsed>=END&&complete===6&&late===0}}
